/* ---- Modo destaque: a aba clicada ocupa a tela inteira ----
   Ao clicar numa aba (categoria ou ferramenta), o conteúdo dela sobe para
   uma camada de tela cheia (body.tab-focus, ver styles.css). Para voltar ao
   normal basta fechar o destaque: botão "Fechar", tecla Esc ou o botão
   "voltar" do celular/navegador. Nada é remontado ao entrar/sair — é o
   mesmo #mainContent, só reposicionado por CSS. */
const TAB_FOCUS_INERT_SELECTORS = ['header.hero', '.flag-stripe', '.controls', '#categorySidebar', '.site-footer', '#backToTop'];
let tabFocusOpener = null;
let tabFocusHistoryPushed = false;
let tabFocusPopExpected = false;

function isTabFocusOpen() {
  return document.body.classList.contains('tab-focus');
}

function setTabFocusInert(on) {
  TAB_FOCUS_INERT_SELECTORS.forEach(sel => document.querySelectorAll(sel).forEach(el => {
    if (on) el.setAttribute('inert', ''); else el.removeAttribute('inert');
  }));
}

// O mapa (Leaflet) só recalcula o tamanho sozinho no redimensionamento da
// janela; ao entrar/sair do destaque o contêiner muda de tamanho sem isso.
function refreshMapSizeAfterFocusChange() {
  if (typeof mapaRedeMap === 'undefined' || !mapaRedeMap || typeof mapaRedeMap.invalidateSize !== 'function') return;
  requestAnimationFrame(() => { try { mapaRedeMap.invalidateSize(); } catch (e) { /* mapa já removido */ } });
}

function syncTabFocusSearch() {
  const mainSearch = document.getElementById('mainSearch');
  const focusSearch = document.getElementById('tabFocusSearch');
  const wrap = document.getElementById('tabFocusSearchWrap');
  if (!mainSearch || !focusSearch || !wrap) return;
  const active = document.querySelector('.filter-chip.active');
  const cat = active ? active.dataset.cat : '';
  // Mesma regra da busca principal: só existe nas abas de equipamentos.
  wrap.style.display = (mainSearch.disabled || cat === 'anotacoes') ? 'none' : '';
  if (focusSearch.value !== mainSearch.value) focusSearch.value = mainSearch.value;
}

function openTabFocus(chip) {
  const main = document.getElementById('mainContent');
  const bar = document.getElementById('tabFocusBar');
  if (!main || !bar || !chip) return false;

  const nameEl = chip.querySelector('span:not(.chip-icon):not(.chip-count)');
  const iconEl = chip.querySelector('.chip-icon');
  document.getElementById('tabFocusName').textContent = nameEl ? nameEl.textContent.trim() : 'Aba';
  document.getElementById('tabFocusIcon').innerHTML = iconEl ? iconEl.innerHTML : '';

  if (!isTabFocusOpen()) {
    tabFocusOpener = chip;
    document.body.classList.add('tab-focus');
    main.setAttribute('role', 'dialog');
    main.setAttribute('aria-modal', 'true');
    main.setAttribute('aria-labelledby', 'tabFocusName');
    setTabFocusInert(true);
    // Uma entrada no histórico faz o botão "voltar" do celular fechar o
    // destaque (em vez de sair do app).
    // O endereço ganha "#aba=<categoria>": dá para copiar/guardar o link da
    // aba e o atalho do app instalado abre direto nela (ver applyHashRoute).
    try {
      history.pushState({ argoTabFocus: true }, '', '#aba=' + encodeURIComponent(chip.dataset.cat || ''));
      tabFocusHistoryPushed = true;
    } catch (e) {
      tabFocusHistoryPushed = false;
    }
  } else {
    // Troca de aba dentro do modo destaque: só atualiza o endereço.
    try { history.replaceState(history.state, '', '#aba=' + encodeURIComponent(chip.dataset.cat || '')); } catch (e) { /* ignora */ }
  }
  if (typeof syncTabFocusJump === 'function') syncTabFocusJump(chip.dataset.cat);

  main.scrollTop = 0;
  refreshMapSizeAfterFocusChange();
  requestAnimationFrame(() => {
    const closeBtn = document.getElementById('tabFocusClose');
    if (closeBtn) { try { closeBtn.focus({ preventScroll: true }); } catch (e) { /* ignora */ } }
  });
  return true;
}

function closeTabFocus(opts) {
  // Primeira linha propositalmente sem tocar em nada além do <body>: o
  // lockApp() pode chamar esta função ainda no carregamento da página.
  if (!document.body.classList.contains('tab-focus')) return;
  document.body.classList.remove('tab-focus');
  const main = document.getElementById('mainContent');
  if (main) {
    main.removeAttribute('role');
    main.removeAttribute('aria-modal');
    main.removeAttribute('aria-labelledby');
  }
  setTabFocusInert(false);

  if (tabFocusHistoryPushed) {
    tabFocusHistoryPushed = false;
    if (!(opts && opts.fromPopstate)) {
      // Desfaz a entrada criada em openTabFocus; o popstate resultante é
      // ignorado (o destaque já foi fechado aqui).
      tabFocusPopExpected = true;
      setTimeout(() => { tabFocusPopExpected = false; }, 600);
      try { history.back(); } catch (e) { tabFocusPopExpected = false; }
    }
  }

  refreshMapSizeAfterFocusChange();
  const opener = tabFocusOpener;
  tabFocusOpener = null;
  if (opener && !mobileSidebarQuery.matches) {
    try { opener.focus({ preventScroll: true }); } catch (e) { /* ignora */ }
  }
}

document.getElementById('tabFocusClose').addEventListener('click', () => closeTabFocus());

document.getElementById('tabFocusSearch').addEventListener('input', (e) => {
  const mainSearch = document.getElementById('mainSearch');
  if (!mainSearch || mainSearch.disabled) return;
  mainSearch.value = e.target.value;
  // Reaproveita o ouvinte da busca principal (botão limpar + render com pausa).
  mainSearch.dispatchEvent(new Event('input', { bubbles: true }));
});

window.addEventListener('popstate', () => {
  if (tabFocusPopExpected) { tabFocusPopExpected = false; return; }
  if (isTabFocusOpen()) {
    tabFocusHistoryPushed = false;
    closeTabFocus({ fromPopstate: true });
  }
});

document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape' || !isTabFocusOpen()) return;
  // Se houver algo mais "por cima" (gaveta de categorias, cartão de abertura,
  // janelas da agenda), o Esc pertence a esse elemento primeiro.
  if (categorySidebar.classList.contains('is-open')) return;
  const greeting = document.getElementById('argoGreetingModal');
  if (greeting && greeting.classList.contains('visible')) return;
  const agendaModalOpen = ['agendaNoteModal', 'agendaSyncModal'].some(id => {
    const m = document.getElementById(id);
    return m && m.style.display === 'flex';
  });
  if (agendaModalOpen) return;
  closeTabFocus();
});

// Sugestões enquanto digita (ver "Sugestões enquanto digita"): busca principal e busca do modo destaque.
const argoSuggestLists = [
  argoAttachSuggest(document.getElementById('mainSearch')),
  argoAttachSuggest(document.getElementById('tabFocusSearch'))
].filter(Boolean);
document.getElementById('searchClearBtn').addEventListener('click', () => argoSuggestLists.forEach(l => l.close()));

document.querySelectorAll('.filter-chip').forEach(c => c.addEventListener('click', () => {
  const prevActive = document.querySelector('.filter-chip.active');
  prevActive.classList.remove('active');
  prevActive.setAttribute('aria-selected', 'false');
  c.classList.add('active');
  c.setAttribute('aria-selected', 'true');
  const chipGroup = c.closest('.filter-group');
  if (chipGroup && chipGroup.classList.contains('collapsed')) {
    chipGroup.classList.remove('collapsed');
    const chipGroupLabel = chipGroup.querySelector('.filter-group-label[role="button"]');
    if (chipGroupLabel) chipGroupLabel.setAttribute('aria-expanded', 'true');
  }
  syncCategoryToggleLabel();
  // Modo destaque: entra ANTES do render() para que painéis como o mapa já
  // nasçam no tamanho final da tela cheia.
  const focused = openTabFocus(c);
  render();
  if (focused) syncTabFocusSearch();
  if (mobileSidebarQuery.matches) {
    closeCategorySidebar();
  } else if (!focused) {
    const controlsEl = document.querySelector('.controls');
    const controlsBottom = controlsEl.getBoundingClientRect().bottom;
    if (controlsBottom < 0 || window.scrollY > controlsEl.offsetTop + 400) {
      controlsEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }
}));

const backToTopBtn = document.getElementById('backToTop');
window.addEventListener('scroll', () => {
  const show = window.scrollY > 600;
  backToTopBtn.classList.toggle('visible', show);
  backToTopBtn.tabIndex = show ? 0 : -1;
}, { passive: true });
backToTopBtn.addEventListener('click', () => {
  window.scrollTo({ top: 0, behavior: 'smooth' });
  document.getElementById('mainSearch').focus();
});


/* ======================= Navegação ampliada =======================
   1) Busca dentro do menu de categorias (filtra os ~30 itens).
   2) Faixa de "Acesso rápido": recentes + ferramentas mais usadas.
   3) Links diretos: #aba=<categoria> (também usado pelos atalhos do app
      instalado, ver manifest.json) e botão "voltar" coerente.
   4) Barra do modo destaque com seletor "Ir para…" e setas ‹ ›.
   5) Teclado: "/" foca a busca, Ctrl/⌘+K troca de aba. */
function navNorm(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

function navChipName(chip) {
  const el = chip && chip.querySelector('span:not(.chip-icon):not(.chip-count)');
  return el ? el.textContent.trim() : '';
}

function navAllChips() {
  return Array.from(document.querySelectorAll('#filterBar .filter-chip[data-cat]'));
}

function goToTab(cat) {
  const chip = document.querySelector('#filterBar .filter-chip[data-cat="' + String(cat).replace(/"/g, '') + '"]');
  if (!chip) return false;
  chip.click();
  return true;
}

function appIsUnlocked() {
  const root = document.getElementById('appRoot');
  return !!root && root.dataset.locked === 'false';
}

/* ---- 1) filtro do menu lateral ---- */
(function initSidebarFilter() {
  const input = document.getElementById('sidebarFilter');
  const empty = document.getElementById('sidebarFilterEmpty');
  if (!input) return;

  function apply() {
    const q = navNorm(input.value);
    let anyVisible = false;
    navAllChips().forEach(chip => {
      if (chip.closest('[data-quick-only]')) return; // não aparecem na grade lateral
      const group = chip.closest('.filter-group');
      const groupName = group ? navNorm((group.querySelector('.filter-group-label') || {}).textContent) : '';
      const hay = navNorm(navChipName(chip)) + ' ' + groupName;
      const match = !q || q.split(/\s+/).every(t => hay.includes(t));
      chip.classList.toggle('nav-hidden', !match);
      if (match) anyVisible = true;
    });
    document.querySelectorAll('#filterBar .filter-group').forEach(g => {
      const has = g.querySelector('.filter-chip:not(.nav-hidden)');
      g.classList.toggle('nav-hidden', !has);
    });
    if (empty) empty.hidden = anyVisible;
  }

  input.addEventListener('input', apply);
  input.addEventListener('keydown', e => {
    if (e.key === 'Enter') {
      const first = Array.from(document.querySelectorAll('#filterBar .filter-chip:not(.nav-hidden)')).find(c => !c.closest('[data-quick-only]'));
      if (first) { e.preventDefault(); first.click(); input.value = ''; apply(); }
    } else if (e.key === 'Escape' && input.value) {
      e.stopPropagation();
      input.value = '';
      apply();
    }
  });
})();

function scrollActiveChipIntoView() {
  const a = document.querySelector('#filterBar .filter-chip.active');
  if (a && a.scrollIntoView) { try { a.scrollIntoView({ block: 'center' }); } catch (e) { /* ignora */ } }
}

/* ---- 2) acesso rápido: recentes + padrão ---- */
const NAV_RECENT_KEY = 'argo_recent_tabs_v1';
// Acesso rápido fixo: são as ferramentas que saíram da grade lateral.
const NAV_DEFAULT_SHORTCUTS = ['agenda', 'mapa', 'tradutor', 'pdftools', 'appsext', 'noticias'];
const NAV_SHORT_LABELS = {
  agenda: 'Agenda Argo', mapa: 'Mapa dos Equipamentos', tradutor: 'Tradutor (Es / En / Fr)',
  pdftools: 'Unificar / Converter PDF', appsext: 'Aplicativos', ferramentas: 'Ferramentas', noticias: 'Notícias do MDS, MEC e Saúde',
  saude: 'RAPS', hospitalar: 'Hospitais', social: 'SUAS', informes: 'Programas', cas: 'CAS', cras: 'CRAS'
};
const NAV_QUICK_MAX = 6;
// Acesso rápido: título curto + subtítulo (mantém o texto completo no tooltip e no leitor de tela).
const NAV_QUICK_META = {
  agenda:   { title: 'Agenda Argo',           sub: 'Calendário e lembretes' },
  mapa:     { title: 'Mapa dos Equipamentos', sub: 'Rede em Boa Vista' },
  tradutor: { title: 'Tradutor',              sub: 'Es · En · Fr' },
  pdftools: { title: 'PDF',                   sub: 'Unificar / Converter' },
  appsext:  { title: 'Aplicativos',           sub: 'Toth, Umbrela, Anona…' },
  noticias: { title: 'Notícias',              sub: 'MDS, MEC e Saúde' }
};

function navReadRecent() {
  try {
    const arr = JSON.parse(localStorage.getItem(NAV_RECENT_KEY) || '[]');
    return Array.isArray(arr) ? arr.filter(x => typeof x === 'string') : [];
  } catch (e) { return []; }
}

function navRememberTab(cat) {
  if (!cat || cat === 'all') return;
  try {
    const list = [cat].concat(navReadRecent().filter(c => c !== cat)).slice(0, 4);
    localStorage.setItem(NAV_RECENT_KEY, JSON.stringify(list));
  } catch (e) { /* sem espaço: só não guarda */ }
}

function renderQuickNav() {
  const host = document.getElementById('quickNav');
  if (!host) return;
  const recents = [];
  const order = NAV_DEFAULT_SHORTCUTS.slice();
  const chips = {};
  navAllChips().forEach(c => { chips[c.dataset.cat] = c; });
  const items = order.filter(c => chips[c]).slice(0, NAV_QUICK_MAX);
  const active = document.querySelector('#filterBar .filter-chip.active');
  const activeCat = active ? active.dataset.cat : '';

  host.innerHTML = items.map(cat => {
    const chip = chips[cat];
    const icon = chip.querySelector('.chip-icon');
    const meta = NAV_QUICK_META[cat];
    const title = meta ? meta.title : (NAV_SHORT_LABELS[cat] || navChipName(chip));
    const sub = meta ? meta.sub : '';
    const isActive = cat === activeCat;
    const isRecent = recents.includes(cat);
    return '<button type="button" class="quick-nav-btn' + (isActive ? ' is-active' : '') + '" data-goto="' + escapeHtml(cat) + '"'
      + (isActive ? ' aria-current="true"' : '')
      + ' aria-label="' + escapeHtml(navChipName(chip)) + '"'
      + ' title="' + escapeHtml(navChipName(chip)) + (isRecent ? ' (usada recentemente)' : '') + '">'
      + '<span class="quick-nav-icon" aria-hidden="true">' + (icon ? icon.innerHTML : '') + '</span>'
      + '<span class="quick-nav-text"><span class="quick-nav-title">' + escapeHtml(title) + '</span>'
      + (sub ? '<span class="quick-nav-sub">' + escapeHtml(sub) + '</span>' : '') + '</span></button>';
  }).join('');
}

(function initQuickNav() {
  const host = document.getElementById('quickNav');
  if (host) host.addEventListener('click', e => {
    const b = e.target.closest ? e.target.closest('[data-goto]') : null;
    if (b) goToTab(b.dataset.goto);
  });
  navAllChips().forEach(chip => chip.addEventListener('click', () => {
    navRememberTab(chip.dataset.cat);
    renderQuickNav();
  }));
  renderQuickNav();
})();

/* ---- 3) links diretos (#aba=...) ---- */
function navHashCat() {
  const m = /^#aba=([^&]+)/.exec(location.hash || '');
  if (!m) return '';
  try { return decodeURIComponent(m[1]); } catch (e) { return ''; }
}

function applyHashRoute() {
  const cat = navHashCat();
  if (!cat || !appIsUnlocked()) return;
  const chip = document.querySelector('#filterBar .filter-chip[data-cat="' + cat.replace(/"/g, '') + '"]');
  // Troca a entrada atual por um endereço limpo; o clique abaixo cria a entrada
  // com "#aba=..." (assim "voltar" fecha a aba em vez de sair do app).
  try { history.replaceState(null, '', location.pathname + location.search); } catch (e) { /* ignora */ }
  if (!chip || cat === 'all') return;
  if (isTabFocusOpen() && document.querySelector('#filterBar .filter-chip.active') === chip) return;
  chip.click();
}

window.addEventListener('hashchange', () => { if (navHashCat()) applyHashRoute(); });

/* ---- 4) seletor "ir para" no modo destaque ---- */
(function initTabFocusJump() {
  const sel = document.getElementById('tabFocusJump');
  if (!sel) return;
  const general = [];
  const groups = [];
  navAllChips().forEach(chip => {
    const g = chip.closest('.filter-group');
    const entry = { cat: chip.dataset.cat, name: navChipName(chip) };
    if (!g) { general.push(entry); return; }
    const label = ((g.querySelector('.filter-group-label') || {}).textContent || '').trim();
    let grp = groups.find(x => x.label === label);
    if (!grp) { grp = { label, items: [] }; groups.push(grp); }
    grp.items.push(entry);
  });
  const opt = e => '<option value="' + escapeHtml(e.cat) + '">' + escapeHtml(e.name) + '</option>';
  sel.innerHTML =
    (general.length ? '<optgroup label="Geral">' + general.map(opt).join('') + '</optgroup>' : '') +
    groups.map(g => '<optgroup label="' + escapeHtml(g.label) + '">' + g.items.map(opt).join('') + '</optgroup>').join('');

  sel.addEventListener('change', () => { if (sel.value) goToTab(sel.value); });
  function step(delta) {
    const values = Array.from(sel.options).map(o => o.value);
    const i = values.indexOf(sel.value);
    if (i < 0) return;
    goToTab(values[(i + delta + values.length) % values.length]);
  }
  document.getElementById('tabFocusPrev').addEventListener('click', () => step(-1));
  document.getElementById('tabFocusNext').addEventListener('click', () => step(1));
})();

function syncTabFocusJump(cat) {
  const sel = document.getElementById('tabFocusJump');
  if (sel && cat && sel.value !== cat) sel.value = cat;
}

/* ---- 5) atalhos de teclado ---- */
document.addEventListener('keydown', e => {
  if (!appIsUnlocked()) return;
  if (document.querySelector('.agenda-modal-overlay.visible, .argo-greeting-overlay.visible')) return;
  const t = e.target;
  const typing = t && (/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName || '') || t.isContentEditable);

  // Ctrl/⌘ + K: ir para outra aba.
  if ((e.ctrlKey || e.metaKey) && !e.altKey && (e.key === 'k' || e.key === 'K')) {
    e.preventDefault();
    if (isTabFocusOpen()) {
      const sel = document.getElementById('tabFocusJump');
      if (sel) { sel.focus(); try { sel.showPicker && sel.showPicker(); } catch (err) { /* ignora */ } }
    } else {
      const f = document.getElementById('sidebarFilter');
      if (mobileSidebarQuery.matches) openCategorySidebar();
      if (f) { f.focus(); f.select(); }
    }
    return;
  }

  // "/": focar a busca disponível.
  if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey && !typing) {
    const main = document.getElementById('mainSearch');
    const focusSearch = document.getElementById('tabFocusSearch');
    const wrap = document.getElementById('tabFocusSearchWrap');
    let target = null;
    if (isTabFocusOpen()) {
      if (wrap && wrap.style.display !== 'none' && focusSearch) target = focusSearch;
      else if (document.getElementById('noticiasFilter')) target = document.getElementById('noticiasFilter');
      else target = document.getElementById('tabFocusJump');
    } else if (main && !main.disabled) target = main;
    else target = document.getElementById('sidebarFilter');
    if (target) { e.preventDefault(); target.focus(); if (target.select) target.select(); }
  }
});

function updateHeaderFooterStats() {
  const totalEl = document.getElementById('heroStatTotal');
  const catEl = document.getElementById('heroStatCategories');
  const footerCountEl = document.getElementById('footerItemCount');

  if (totalEl) totalEl.textContent = DATA.length;

  if (catEl) {
    const chips = document.querySelectorAll('.filter-chip[data-cat]:not([data-cat="all"]):not([data-cat="anotacoes"])');
    catEl.textContent = chips.length;
  }

  if (footerCountEl) {
    footerCountEl.textContent = `${DATA.length} registros no diretório`;
  }

  const footerYearEl = document.getElementById('footerYear');
  if (footerYearEl) {
    footerYearEl.textContent = new Date().getFullYear();
  }
}

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').then(reg => {

      // Já existe uma atualização baixada esperando para entrar em ação?
      if (reg.waiting) ativarAtualizacao(reg.waiting);

      // Fica de olho em novas atualizações encontradas a partir de agora
      reg.addEventListener('updatefound', () => {
        const novoWorker = reg.installing;
        novoWorker.addEventListener('statechange', () => {
          if (novoWorker.state === 'installed' && navigator.serviceWorker.controller) {
            ativarAtualizacao(novoWorker);
          }
        });
      });

      // O navegador só checa sw.js sozinho quando a página é recarregada/
      // navegada de novo. Como o app costuma ficar com a aba aberta por
      // horas (às vezes dias), isso sozinho não é suficiente para pegar
      // uma atualização publicada nesse meio tempo. Por isso, além disso,
      // força a checagem manual (reg.update()) sempre que a aba volta a
      // ficar visível (o usuário troca de aba/app e volta) e também em
      // intervalo fixo enquanto a aba permanece aberta em primeiro plano.
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') reg.update().catch(() => {});
      });
      setInterval(() => {
        if (document.visibilityState === 'visible') reg.update().catch(() => {});
      }, 30 * 60 * 1000); // a cada 30 minutos, só quando a aba está em foco
    }).catch(() => {
    });

    // Quando o novo Service Worker assume o controle:
    //  • primeira instalação (a página ainda não tinha Service Worker): não há
    //    versão nova a carregar, então não recarrega — antes recarregava já na
    //    primeira visita;
    //  • app trancado (tela de senha): recarrega na hora, sem custo;
    //  • app em uso: NÃO recarrega no meio do trabalho (isso jogava a pessoa
    //    de volta na tela de senha). Mostra um aviso discreto com o botão
    //    "Atualizar" e recarrega sozinho na próxima vez que o app for trancado.
    const jaTinhaControlador = !!navigator.serviceWorker.controller;
    let jaRecarregou = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (!jaTinhaControlador || jaRecarregou) return;
      const appRoot = document.getElementById('appRoot');
      const emUso = appRoot && appRoot.dataset.locked === 'false';
      if (!emUso) {
        jaRecarregou = true;
        window.location.reload();
        return;
      }
      window.__argoUpdatePending = true;
      const greeting = document.getElementById('argoGreetingModal');
      // Com o cartão de abertura na tela, o aviso espera ele ser fechado
      // (ver argoDismissGreeting) para não ficar por cima dos botões.
      if (!(greeting && greeting.classList.contains('visible'))) argoShowUpdateToast();
    });
  });
}

function ativarAtualizacao(worker) {
  worker.postMessage({ type: 'SKIP_WAITING' });
}

// Aviso discreto de "nova versão disponível" (ver controllerchange acima).
function argoShowUpdateToast() {
  if (document.getElementById('argoUpdateToast')) return;
  const el = document.createElement('div');
  el.id = 'argoUpdateToast';
  el.setAttribute('role', 'status');
  el.style.cssText = 'position:fixed;left:50%;bottom:calc(16px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);z-index:1300;width:max-content;max-width:calc(100vw - 24px);display:flex;align-items:center;gap:12px;padding:9px 10px 9px 16px;border-radius:14px;background:#0c2946;color:#f6e7bd;border:1px solid rgba(243,213,138,.45);box-shadow:0 12px 30px -8px rgba(0,0,0,.6);font:600 13px Inter,system-ui,sans-serif;';
  el.innerHTML = '<span>Nova versão do Argo disponível.</span>' +
    '<button type="button" style="flex-shrink:0;border:none;border-radius:10px;padding:7px 14px;background:linear-gradient(135deg,#29ABE2,#0091C2);color:#fff;font:700 13px Inter,system-ui,sans-serif;cursor:pointer;">Atualizar</button>';
  el.querySelector('button').addEventListener('click', () => window.location.reload());
  document.body.appendChild(el);
}

/* ============================================================
   AGENDA ARGO — calendário com feriados/pagamentos fixos e anotações
   pessoais sincronizadas entre aparelhos (Firebase Firestore). Mesmo
   princípio das outras abas de ferramenta: o SDK do Firebase só é baixado
   do gstatic na primeira vez que o usuário configura um código de
   sincronização, então não entra no cache offline do Service Worker.
   Sem um código configurado, o calendário funciona normalmente (feriados e
   pagamentos aparecem), só as anotações ficam indisponíveis até sincronizar.

   A agenda é PERENE: o ano exibido (AGENDA_YEAR, logo abaixo) é sempre o
   ano atual, calculado sozinho — nada precisa ser trocado no código na
   virada do ano. O que precisa de atualização TODO ANO são os DADOS de
   feriados/pontos facultativos/pagamentos de AGENDA_DATA_BY_YEAR, abaixo:
   sem o bloco do ano corrente ali, o calendário continua funcionando
   normalmente (troca de mês, anotações, sincronização), só sem as
   etiquetas de feriado/pagamento daquele ano.

   COMO ATUALIZAR A CADA ANO: copie o bloco do último ano cadastrado,
   troque o número do ano nas chaves (ex.: "2026-01-01" → "2027-01-01") e
   preencha as datas a partir do Diário Oficial do Município de Boa Vista
   (feriados e pontos facultativos) e do calendário oficial de pagamentos
   (Bolsa Família/Caixa e 13º do INSS) daquele ano. Basta ACRESCENTAR um
   novo bloco — nunca é preciso apagar os anos anteriores. */
